-- Egg White Veggie Scramble
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'egg-white-veggie-scramble'),
  'Sebzeli Yumurta Akı',
  'Egg White Veggie Scramble',
  'breakfast',
  240, 32, 10, 8,
  12,
  'MALZEMELER:
- 250 ml yumurta akı
- 1 bütün yumurta
- 60 g ıspanak
- 60 g mantar
- 1 tatlı kaşığı zeytinyağı
- tuz ve karabiber

HAZIRLANIŞI:
1. Zeytinyağını yapışmaz bir tavada orta ateşte ısıtın.
2. Mantarları suyunu salıp hafif kızarana kadar pişirin.
3. Ispanağı ekleyip solana kadar pişirin.
4. Yumurta akı ve bütün yumurtayı ekleyip donana kadar yavaşça çevirin.
5. Tuz ve karabiberle tatlandırıp hemen servis edin.',
  'INGREDIENTS:
- 250 ml egg whites
- 1 whole egg
- 60 g spinach
- 60 g mushrooms
- 1 dessertspoon olive oil
- salt and pepper

METHOD:
1. Warm the olive oil in a non-stick pan over medium heat.
2. Cook the mushrooms until they release their water and start to brown.
3. Add the spinach and cook until it wilts.
4. Pour in the egg whites and the whole egg, then fold gently until set.
5. Season with salt and pepper and serve straight away.',
  ARRAY['high_protein', 'low_calorie']::text[],
  'american',
  ARRAY['vegetarian', 'pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/egg-white-veggie-scramble.webp'
)
