-- Banana Protein Pancakes
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'banana-protein-pancakes'),
  'Muzlu Protein Pankek',
  'Banana Protein Pancakes',
  'breakfast',
  505, 40, 55, 14,
  15,
  'MALZEMELER:
- 1 olgun muz
- 2 yumurta
- 40 g yulaf ezmesi
- 30 g vanilyalı whey protein tozu
- 1 çay kaşığı kabartma tozu
- 1 tatlı kaşığı hindistancevizi yağı
- 1 yemek kaşığı akçaağaç şurubu

HAZIRLANIŞI:
1. Muz, yumurta, yulaf, protein tozu ve kabartma tozunu pürüzsüz olana kadar blenderdan geçirin.
2. Yulafların yumuşaması için hamuru 5 dakika dinlendirin.
3. Hafif yağlanmış tavada kısık-orta ateşte, her yüzü yaklaşık 2 dakika olacak şekilde pişirin.
4. Üst üste dizip akçaağaç şurubu gezdirin.',
  'INGREDIENTS:
- 1 ripe banana
- 2 eggs
- 40 g rolled oats
- 30 g vanilla whey protein powder
- 1 tsp baking powder
- 1 dessertspoon coconut oil
- 1 tbsp maple syrup

METHOD:
1. Blend the banana, eggs, oats, protein powder and baking powder smooth.
2. Rest the batter for 5 minutes so the oats soften.
3. Cook spoonfuls in a lightly oiled pan over medium-low heat, about 2 minutes a side.
4. Stack and finish with maple syrup.',
  ARRAY['high_protein', 'bulking']::text[],
  'american',
  ARRAY['vegetarian', 'pork_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/banana-protein-pancakes.webp'
)
