-- Greek Yogurt Power Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'greek-yogurt-power-bowl'),
  'Süzme Yoğurtlu Güç Kasesi',
  'Greek Yogurt Power Bowl',
  'breakfast',
  415, 34, 38, 14,
  5,
  'MALZEMELER:
- 200 g süzme yoğurt
- 30 g karışık orman meyvesi
- 20 g ceviz
- 1 yemek kaşığı chia tohumu
- 1 tatlı kaşığı bal

HAZIRLANIŞI:
1. Süzme yoğurdu geniş bir kaseye alın.
2. Üzerine orman meyvelerini, cevizi ve chia tohumunu serpin.
3. Balı gezdirip hemen tüketin.',
  'INGREDIENTS:
- 200 g Greek yogurt
- 30 g mixed berries
- 20 g walnuts
- 1 tbsp chia seeds
- 1 dessertspoon honey

METHOD:
1. Spoon the Greek yogurt into a wide bowl.
2. Scatter the berries, walnuts and chia seeds across the top.
3. Finish with honey and eat immediately.',
