-- Peanut Butter Protein Toast
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'peanut-butter-protein-toast'),
  'Fıstık Ezmeli Protein Tost',
  'Peanut Butter Protein Toast',
  'breakfast',
  460, 26, 44, 20,
  6,
  'MALZEMELER:
- 2 dilim tam buğday ekmeği
- 2 yemek kaşığı doğal fıstık ezmesi
- 1 muz
- 2 yumurta
- 1 çimdik tarçın

HAZIRLANIŞI:
1. Ekmeği altın rengi ve sert olana kadar kızartın.
2. Ekmek kızarırken yumurtaları dilediğiniz gibi haşlayın veya pişirin.
3. Fıstık ezmesini iki dilime de sürün.
4. Üzerine muz dilimlerini dizin, tarçın serpin ve yumurtaları yanında servis edin.',
  'INGREDIENTS:
- 2 slices wholemeal bread
- 2 tbsp peanut butter
- 1 banana
- 2 eggs
- 1 pinch cinnamon

METHOD:
1. Toast the bread until it is golden and firm.
2. Boil or fry the eggs to your liking while the bread toasts.
3. Spread the peanut butter across both slices.
4. Lay banana slices over the top, dust with cinnamon, and serve the eggs alongside.',
  ARRAY['high_protein', 'budget_friendly']::text[],
  'american',
  ARRAY['vegetarian', 'pork_free', 'dairy_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/peanut-butter-protein-toast.webp'
)
