-- Savory Oats with Egg
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'savory-oats-with-egg'),
  'Yumurtalı Tuzlu Yulaf',
  'Savory Oats with Egg',
  'breakfast',
  450, 28, 48, 16,
  15,
  'MALZEMELER:
- 60 g yulaf ezmesi
- 250 ml sebze suyu
- 2 yumurta
- 30 g çedar peyniri
- 1 yemek kaşığı yeşil soğan
- tuz ve karabiber

HAZIRLANIŞI:
1. Yulafı sebze suyunda 6 dakika, karıştırarak, kremamsı olana kadar pişirin.
2. Çedar peynirini eriyene kadar karıştırın.
3. Yumurtaları ayrı bir tavada pişirin.
4. Yulafın üzerine yumurtaları koyun, yeşil soğanı serpip tatlandırın.',
  'INGREDIENTS:
- 60 g rolled oats
- 250 ml vegetable stock
- 2 eggs
- 30 g cheddar cheese
- 1 tbsp spring onion
- salt and pepper

METHOD:
1. Simmer the oats in the stock for 6 minutes, stirring, until creamy.
2. Stir the cheddar through until it melts.
3. Fry the eggs in a separate pan.
4. Top the oats with the eggs, scatter the spring onion and season.',
