-- Protein French Toast
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'protein-french-toast'),
  'Proteinli Fransız Tostu',
  'Protein French Toast',
  'breakfast',
  510, 42, 50, 16,
  12,
  'MALZEMELER:
- 3 dilim tam buğday ekmeği
- 2 yumurta
- 120 ml süt
- 25 g vanilyalı whey protein tozu
- 1 çay kaşığı tarçın
- 1 tatlı kaşığı tereyağı

HAZIRLANIŞI:
1. Yumurta, süt, protein tozu ve tarçını geniş bir kapta çırpın.
2. Her ekmek dilimini iki yüzünde 20 saniye bekletin.
3. Tereyağında orta ateşte, her yüzü yaklaşık 2 dakika, altın rengi olana kadar kızartın.',
  'INGREDIENTS:
- 3 slices wholemeal bread
- 2 eggs
- 120 ml milk
- 25 g vanilla whey protein powder
- 1 tsp cinnamon
- 1 dessertspoon butter

METHOD:
1. Whisk the eggs, milk, protein powder and cinnamon in a shallow dish.
2. Soak each slice of bread for 20 seconds a side.
3. Fry in the butter over medium heat until golden, about 2 minutes a side.',
  ARRAY['high_protein', 'bulking']::text[],
  'american',
  ARRAY['vegetarian', 'pork_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/protein-french-toast.webp'
)
