-- Turkey and Egg Breakfast Wrap
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'turkey-bacon-breakfast-wrap'),
  'Hindili Yumurtalı Kahvaltı Dürümü',
  'Turkey and Egg Breakfast Wrap',
  'breakfast',
  425, 36, 34, 16,
  12,
  'MALZEMELER:
- 1 tam buğday tortilla
- 60 g dilimli hindi göğsü
- 2 yumurta
- 30 g çedar peyniri
- 30 g taze ıspanak
- tuz ve karabiber

HAZIRLANIŞI:
1. Yumurtaları kızgın tavada karıştırıp tatlandırın.
2. Tortillayı aynı tavada her yüzü 20 saniye olacak şekilde ısıtın.
3. Hindiyi, yumurtayı, peyniri ve ıspanağı ortaya dizin.
4. Uçlarını kapatıp sıkıca sarın ve ikiye kesin.',
  'INGREDIENTS:
- 1 wholemeal tortilla
- 60 g sliced turkey breast
- 2 eggs
- 30 g cheddar cheese
- 30 g baby spinach
- salt and pepper

METHOD:
1. Scramble the eggs in a hot pan and season them.
2. Warm the tortilla for 20 seconds a side in the same pan.
3. Lay the turkey, eggs, cheese and spinach down the middle.
4. Fold the ends in, roll tightly, and slice in half.',
