insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'smoked-salmon-bagel-stack'),
  'Füme Somonlu Yumurta Tabağı',
  'Smoked Salmon and Egg Plate',
  'breakfast',
  400, 34, 26, 18,
  10,
  'MALZEMELER:
- 80 g füme somon
- 2 yumurta
- 2 dilim çavdar ekmeği
- 30 g krem peynir
- 1 yemek kaşığı dereotu
- karabiber

HAZIRLANIŞI:
1. Yumurtaları 6 dakika poşe edin veya rafadan haşlayın.
2. Çavdar ekmeğini kızartıp krem peyniri sürün.
3. Somonu ekmeğin üzerine dizin, yumurtaları yanına koyun.
4. Dereotu ve taze çekilmiş karabiberle bitirin.',
  'INGREDIENTS:
- 80 g smoked salmon
- 2 eggs
- 2 slices rye bread
- 30 g cream cheese
- 1 tbsp dill
- black pepper

METHOD:
1. Poach or soft-boil the eggs for 6 minutes.
2. Toast the rye bread and spread it with the cream cheese.
3. Lay the smoked salmon over the bread and set the eggs alongside.
4. Finish with dill and a grind of black pepper.',
