-- Apple Cinnamon Protein Oatmeal
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'apple-cinnamon-protein-oatmeal'),
  'Elmalı Tarçınlı Protein Yulafı',
  'Apple Cinnamon Protein Oatmeal',
  'breakfast',
  440, 32, 56, 10,
  12,
  'MALZEMELER:
- 60 g yulaf ezmesi
- 250 ml süt
- 1 elma
- 25 g vanilyalı whey protein tozu
- 1 çay kaşığı tarçın
- 10 g ceviz

HAZIRLANIŞI:
1. Elmayı küp doğrayıp yulaf ve sütle 7 dakika pişirin.
2. Tencereyi ateşten alın ve protein tozunu karıştırın — kaynayan süte eklemek tozu topaklandırır.
3. Tarçını ekleyin, üzerine ceviz serpip ılık servis edin.',
  'INGREDIENTS:
- 60 g rolled oats
- 250 ml milk
- 1 apple
- 25 g vanilla whey protein powder
- 1 tsp cinnamon
- 10 g walnuts

METHOD:
1. Dice the apple and simmer it with the oats and milk for 7 minutes.
2. Take the pan off the heat and stir the protein powder through — adding it to boiling milk makes it grainy.
3. Stir in the cinnamon, top with walnuts and serve warm.',
  ARRAY['high_protein', 'budget_friendly']::text[],
  'american',
  ARRAY['vegetarian', 'pork_free']::text[],
  ARRAY['en']::text[],
