-- High-Protein Breakfast Burrito
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'high-protein-breakfast-burrito'),
  'Yüksek Proteinli Kahvaltı Burritosu',
  'High-Protein Breakfast Burrito',
  'breakfast',
  580, 44, 52, 22,
  18,
  'MALZEMELER:
- 1 büyük tam buğday tortilla
- 3 yumurta
- 80 g siyah fasulye
- 60 g yağsız dana kıyma
- 30 g çedar peyniri
- 2 yemek kaşığı salsa sos
- kimyon, tuz, karabiber

HAZIRLANIŞI:
1. Kıymayı kimyonla, pembelik kalmayana kadar kavurun.
2. Siyah fasulyeyi ekleyip ısınmasını bekleyin.
3. Yumurtaları ikinci bir tavada karıştırıp tatlandırın.
4. Tortillayı ısıtın; kıyma, fasulye, yumurta, peynir ve salsa sosu koyup sıkıca sarın.',
  'INGREDIENTS:
- 1 large wholemeal tortilla
- 3 eggs
- 80 g black beans
- 60 g lean ground beef
- 30 g cheddar cheese
- 2 tbsp salsa
- cumin, salt, pepper

METHOD:
1. Brown the ground beef with the cumin until no pink remains.
2. Add the black beans and warm them through.
3. Scramble the eggs in a second pan and season them.
4. Warm the tortilla, load it with the beef, beans, eggs, cheese and salsa, then roll it tight.',
  ARRAY['high_protein', 'bulking']::text[],
  'american',
  ARRAY['pork_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/high-protein-breakfast-burrito.webp'
)
