-- Vanilla Protein Chia Pudding
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'protein-chia-pudding'),
  'Vanilyalı Protein Chia Puding',
  'Vanilla Protein Chia Pudding',
  'breakfast',
  370, 30, 26, 16,
  8,
  'MALZEMELER:
- 3 yemek kaşığı chia tohumu
- 250 ml badem sütü
- 30 g vanilyalı whey protein tozu
- 80 g ahududu
- 1 tatlı kaşığı akçaağaç şurubu

HAZIRLANIŞI:
1. Chia tohumu, badem sütü ve protein tozunu bir kavanozda çırpın.
2. 5 dakika sonra tekrar çırpın; tohumlar dipte topaklanmasın.
3. En az 4 saat buzdolabında bekletin, sonra ahududu ve akçaağaç şurubuyla servis edin.',
  'INGREDIENTS:
- 3 tbsp chia seeds
- 250 ml almond milk
- 30 g vanilla whey protein powder
- 80 g raspberries
- 1 dessertspoon maple syrup

METHOD:
1. Whisk the chia seeds, almond milk and protein powder in a jar.
2. Whisk again after 5 minutes so the seeds do not clump at the bottom.
3. Refrigerate for at least 4 hours, then top with raspberries and maple syrup.',
  ARRAY['high_protein', 'toning']::text[],
  'american',
  ARRAY['vegetarian', 'pork_free', 'gluten_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/protein-chia-pudding.webp'
)
