-- Chicken and Rice Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'chicken-and-rice-bowl'),
  'Tavuklu Pilav Kasesi',
  'Chicken and Rice Bowl',
  'lunch',
  580, 52, 62, 14,
  25,
  'MALZEMELER:
- 180 g tavuk göğsü
- 80 g pirinç (kuru ölçü)
- 100 g brokoli
- 1 yemek kaşığı zeytinyağı
- 1 tatlı kaşığı toz kırmızı biber
- tuz ve karabiber

HAZIRLANIŞI:
1. Pirinci yıkayıp iki katı suda 15 dakika pişirin.
2. Tavuğu toz kırmızı biber, tuz ve karabiberle tatlandırın.
3. Tavuğu zeytinyağında orta-yüksek ateşte her yüzü 5 dakika mühürleyin, sonra 3 dakika dinlendirin.
4. Brokoliyi diri kalması için 4 dakika buharda pişirin.
5. Tavuğu dilimleyip kaseyi kurun: pilav, brokoli, tavuk.',
  'INGREDIENTS:
- 180 g chicken breast
- 80 g white rice (dry weight)
- 100 g broccoli
- 1 tbsp olive oil
- 1 dessertspoon paprika
- salt and pepper

METHOD:
1. Rinse the rice and simmer it in twice its volume of water for 15 minutes.
2. Season the chicken with the paprika, salt and pepper.
3. Sear the chicken in the olive oil over medium-high heat, 5 minutes a side, then rest it for 3 minutes.
4. Steam the broccoli for 4 minutes so it keeps its bite.
5. Slice the chicken and build the bowl: rice, broccoli, chicken.',
  ARRAY['high_protein', 'bulking']::text[],
  'american',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/chicken-and-rice-bowl.webp'
)
