-- Tuna Avocado Wrap
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'tuna-avocado-wrap'),
  'Ton Balıklı Avokado Dürüm',
  'Tuna Avocado Wrap',
  'lunch',
  470, 38, 34, 20,
  10,
  'MALZEMELER:
- 1 tam buğday tortilla
- 150 g ton balığı (suyu süzülmüş)
- 1 avokado
- 2 yaprak marul
- 1 yemek kaşığı limon suyu
- tuz ve karabiber

HAZIRLANIŞI:
1. Avokadoyu limon suyu, tuz ve karabiberle ezin.
2. Suyu süzülmüş ton balığını avokadoya karıştırın.
3. Karışımı tortillanın ortasına yayıp üzerine marulu dizin.
4. Sıkıca sarıp çapraz kesin.',
  'INGREDIENTS:
- 1 wholemeal tortilla
- 150 g canned tuna (drained)
- 1 avocado
- 2 leaves lettuce
- 1 tbsp lemon juice
- salt and pepper

METHOD:
1. Mash the avocado with the lemon juice, salt and pepper.
2. Fold the drained tuna through the avocado.
3. Spread the mixture down the middle of the tortilla and lay the lettuce over it.
4. Roll it tightly and cut it on the diagonal.',
  ARRAY['high_protein', 'budget_friendly']::text[],
  'american',
  ARRAY['pork_free', 'dairy_free']::text[],
  ARRAY['en']::text[],
