-- Beef and Sweet Potato Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'beef-and-sweet-potato-bowl'),
  'Dana Etli Tatlı Patates Kasesi',
  'Beef and Sweet Potato Bowl',
  'lunch',
  595, 46, 58, 20,
  30,
  'MALZEMELER:
- 160 g yağsız dana kıyma
- 250 g tatlı patates
- 80 g taze fasulye
- 1 yemek kaşığı zeytinyağı
- 1 diş sarımsak
- kimyon, tuz, karabiber

HAZIRLANIŞI:
1. Tatlı patatesi küp doğrayın, yağın yarısıyla karıştırıp 200 derecede 25 dakika fırınlayın.
2. Kıymayı sarımsak ve kimyonla kalan yağda kavurun.
3. Taze fasulyeyi 5 dakika buharda pişirin.
4. Hepsini bir kasede birleştirip tuz ve karabiberle tatlandırın.',
  'INGREDIENTS:
- 160 g lean ground beef
- 250 g sweet potato
- 80 g green beans
- 1 tbsp olive oil
- 1 clove garlic
- cumin, salt, pepper

METHOD:
1. Cube the sweet potato, toss it in half the oil, and roast at 200 degrees for 25 minutes.
2. Brown the beef with the garlic and cumin in the rest of the oil.
3. Steam the green beans for 5 minutes.
4. Combine everything in a bowl and season to taste.',
