-- Grilled Chicken Caesar Salad
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'grilled-chicken-caesar-salad'),
  'Izgara Tavuklu Sezar Salata',
  'Grilled Chicken Caesar Salad',
  'lunch',
  455, 44, 20, 22,
  20,
  'MALZEMELER:
- 160 g tavuk göğsü
- 150 g marul
- 25 g parmesan peyniri
- 2 yemek kaşığı süzme yoğurt
- 1 çay kaşığı dijon hardalı
- 1 yemek kaşığı limon suyu
- 1 yemek kaşığı zeytinyağı

HAZIRLANIŞI:
1. Tavuğu her yüzü 6 dakika ızgarada pişirip dinlendirin.
2. Yoğurt, hardal, limon suyu ve zeytinyağını çırparak sos yapın.
3. Marulu elle koparıp kaseye alın ve sosla harmanlayın.
4. Tavuğu üzerine dilimleyip rendelenmiş parmesanla bitirin.',
  'INGREDIENTS:
- 160 g chicken breast
- 150 g romaine lettuce
- 25 g parmesan cheese
- 2 tbsp Greek yogurt
- 1 tsp dijon mustard
- 1 tbsp lemon juice
- 1 tbsp olive oil

METHOD:
1. Grill the chicken for 6 minutes a side and rest it.
2. Whisk the yogurt, mustard, lemon juice and olive oil into a dressing.
3. Tear the lettuce into a bowl and toss it through the dressing.
4. Slice the chicken over the top and finish with grated parmesan.',
