-- Turkey Quinoa Power Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'turkey-quinoa-power-bowl'),
  'Hindili Kinoa Güç Kasesi',
  'Turkey Quinoa Power Bowl',
  'lunch',
  515, 45, 48, 16,
  25,
  'MALZEMELER:
- 160 g hindi kıyma
- 70 g kinoa (kuru ölçü)
- 80 g cherry domates
- 60 g salatalık
- 1 yemek kaşığı zeytinyağı
- 1 yemek kaşığı limon suyu
- tuz ve karabiber

HAZIRLANIŞI:
1. Kinoayı yıkayıp 15 dakika haşlayın, sonra çatalla kabartın.
2. Hindi kıymasını zeytinyağında kavurup tatlandırın.
3. Domatesleri ikiye bölün, salatalığı küp doğrayın.
4. Hepsini limon suyuyla harmanlayın.',
  'INGREDIENTS:
- 160 g ground turkey
- 70 g quinoa (dry weight)
- 80 g cherry tomatoes
- 60 g cucumber
- 1 tbsp olive oil
- 1 tbsp lemon juice
- salt and pepper

METHOD:
1. Rinse the quinoa and simmer it for 15 minutes, then fluff it.
2. Brown the ground turkey in the olive oil and season it.
3. Halve the tomatoes and dice the cucumber.
4. Toss everything together with the lemon juice.',
