-- Salmon Rice Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'salmon-poke-style-bowl'),
  'Somonlu Pirinç Kasesi',
  'Salmon Rice Bowl',
  'lunch',
  605, 42, 60, 22,
  20,
  'MALZEMELER:
- 160 g somon fileto
- 80 g pirinç (kuru ölçü)
- 1 avokado
- 50 g edamame
- 1 yemek kaşığı soya sosu
- 1 çay kaşığı susam

HAZIRLANIŞI:
1. Pirinci pişirip oda sıcaklığına gelene kadar soğutun.
2. Somonu her yüzü 3 dakika, ortası pembe kalacak şekilde mühürleyin.
3. Avokadoyu dilimleyin, edamameyi ısıtın.
4. Kaseyi kurun, soya sosunu gezdirip susamı serpin.',
  'INGREDIENTS:
- 160 g salmon fillet
- 80 g sushi rice (dry weight)
- 1 avocado
- 50 g edamame
- 1 tbsp soy sauce
- 1 tsp sesame seeds

METHOD:
1. Cook the rice and let it cool to room temperature.
2. Sear the salmon for 3 minutes a side, leaving the centre pink.
3. Slice the avocado and warm the edamame.
4. Build the bowl, pour over the soy sauce and scatter the sesame seeds.',
  ARRAY['high_protein', 'bulking']::text[],
  'american',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
