  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'shrimp-and-quinoa-salad'),
  'Karidesli Kinoa Salatası',
  'Shrimp and Quinoa Salad',
  'lunch',
  410, 38, 38, 12,
  20,
  'MALZEMELER:
- 160 g karides (temizlenmiş)
- 60 g kinoa (kuru ölçü)
- 80 g salatalık
- 60 g cherry domates
- 1 avuç maydanoz
- 1 yemek kaşığı zeytinyağı
- 1 yemek kaşığı limon suyu

HAZIRLANIŞI:
1. Kinoayı 15 dakika haşlayıp soğutun.
2. Karidesleri her yüzü 2 dakika, rengi dönene kadar pişirin.
3. Salatalığı küp doğrayın, domatesleri ikiye bölün, maydanozu kıyın.
4. Hepsini zeytinyağı ve limon suyuyla harmanlayın.',
  'INGREDIENTS:
- 160 g shrimp (peeled)
- 60 g quinoa (dry weight)
- 80 g cucumber
- 60 g cherry tomatoes
- 1 handful parsley
- 1 tbsp olive oil
- 1 tbsp lemon juice

METHOD:
1. Simmer the quinoa for 15 minutes and cool it.
2. Sear the shrimp for 2 minutes a side until they turn opaque.
3. Dice the cucumber, halve the tomatoes and chop the parsley.
4. Toss everything with the olive oil and lemon juice.',
