-- Turkey Club Lettuce Wraps
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'turkey-club-lettuce-wraps'),
  'Hindili Marul Sarma',
  'Turkey Club Lettuce Wraps',
  'lunch',
  320, 36, 12, 14,
  12,
  'MALZEMELER:
- 150 g dilimli hindi göğsü
- 6 yaprak büyük marul yaprağı
- 1 avokado
- 1 domates
- 2 yemek kaşığı süzme yoğurt
- 1 çay kaşığı dijon hardalı

HAZIRLANIŞI:
1. Süzme yoğurt ve hardalı karıştırarak sos yapın.
2. Marul yapraklarını düz serip sosu üzerlerine sürün.
3. İçine hindiyi, dilimlenmiş avokadoyu ve domatesi dizin.
4. Her yaprağı paket gibi katlayın.',
  'INGREDIENTS:
- 150 g sliced turkey breast
- 6 leaves large lettuce leaves
- 1 avocado
- 1 tomato
- 2 tbsp Greek yogurt
- 1 tsp dijon mustard

METHOD:
1. Mix the Greek yogurt and mustard into a dressing.
2. Lay the lettuce leaves out flat and spread the dressing across them.
3. Layer the turkey, sliced avocado and sliced tomato inside.
4. Fold each leaf into a parcel.',
  ARRAY['high_protein', 'low_calorie']::text[],
  'american',
  ARRAY['pork_free', 'gluten_free']::text[],
  ARRAY['en']::text[],
