-- Tuna and Cottage Cheese Jacket Potato
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'cottage-cheese-tuna-jacket'),
  'Ton Balıklı Süzme Peynirli Fırın Patates',
  'Tuna and Cottage Cheese Jacket Potato',
  'lunch',
  470, 42, 58, 8,
  45,
  'MALZEMELER:
- 300 g fırınlık patates
- 120 g ton balığı (suyu süzülmüş)
- 120 g süzme peynir
- 1 yemek kaşığı yeşil soğan
- tuz ve karabiber

HAZIRLANIŞI:
1. Patatesi çatalla delip 200 derecede 45 dakika fırınlayın.
2. Suyu süzülmüş ton balığını süzme peynire karıştırıp tatlandırın.
3. Patatesi ortadan yarıp karışımı içine doldurun.
4. Üzerine yeşil soğan serpin.',
  'INGREDIENTS:
- 300 g baking potato
- 120 g canned tuna (drained)
- 120 g cottage cheese
- 1 tbsp spring onion
- salt and pepper

METHOD:
1. Pierce the potato and bake it at 200 degrees for 45 minutes.
2. Fold the drained tuna into the cottage cheese and season it.
3. Split the potato open and pile the mixture in.
4. Scatter the spring onion over the top.',
  ARRAY['high_protein', 'budget_friendly']::text[],
  'american',
  ARRAY['pork_free', 'gluten_free']::text[],
