-- Chicken Pesto Pasta Salad
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'chicken-pesto-pasta-salad'),
  'Pestolu Tavuklu Makarna Salatası',
  'Chicken Pesto Pasta Salad',
  'lunch',
  605, 44, 58, 22,
  25,
  'MALZEMELER:
- 90 g tam buğday makarna (kuru ölçü)
- 160 g tavuk göğsü
- 2 yemek kaşığı fesleğen pesto
- 80 g cherry domates
- 30 g roka
- tuz ve karabiber

HAZIRLANIŞI:
1. Makarnayı haşlayın, süzün ve soğuk sudan geçirin.
2. Tavuğu her yüzü 6 dakika ızgarada pişirip dilimleyin.
3. Makarnayı pesto ile her tanesi kaplanana kadar harmanlayın.
4. İkiye bölünmüş domatesleri, rokayı ve tavuğu ekleyin.',
  'INGREDIENTS:
- 90 g wholemeal pasta (dry weight)
- 160 g chicken breast
- 2 tbsp basil pesto
- 80 g cherry tomatoes
- 30 g rocket
- salt and pepper

METHOD:
1. Boil the pasta, drain it and run it under cold water.
2. Grill the chicken for 6 minutes a side, then slice it.
3. Toss the pasta with the pesto until every piece is coated.
4. Fold in the halved tomatoes, rocket and chicken.',
  ARRAY['high_protein', 'bulking']::text[],
  'american',
  ARRAY['pork_free', 'dairy_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/chicken-pesto-pasta-salad.webp'
)
