-- Steak and Egg Plate
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'steak-and-egg-plate'),
  'Bonfileli Yumurta Tabağı',
  'Steak and Egg Plate',
  'lunch',
  510, 54, 6, 30,
  20,
  'MALZEMELER:
- 180 g dana bonfile
- 3 yumurta
- 60 g roka
- 1 yemek kaşığı zeytinyağı
- tuz ve karabiber

HAZIRLANIŞI:
1. Bonfileyi oda sıcaklığına getirip bolca tuzlayın.
2. Çok kızgın tavada, orta-az pişmiş için her yüzü 3 dakika mühürleyin.
3. Eti 5 dakika dinlendirin — erken kesmek suyunu kaybettirir.
4. Yumurtaları aynı tavada pişirip her şeyi rokanın üzerinde servis edin.',
  'INGREDIENTS:
- 180 g beef sirloin
- 3 eggs
- 60 g rocket
- 1 tbsp olive oil
- salt and black pepper

METHOD:
1. Bring the steak to room temperature and season it heavily.
2. Sear it in a very hot pan, 3 minutes a side for medium-rare.
3. Rest the steak for 5 minutes — cutting it early loses the juices.
4. Fry the eggs in the same pan and serve everything over the rocket.',
  ARRAY['high_protein', 'bulking']::text[],
  'american',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY['en']::text[],
