-- Baked Salmon with Sweet Potato and Asparagus
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'baked-salmon-asparagus'),
  'Fırında Somon, Tatlı Patates ve Kuşkonmaz',
  'Baked Salmon with Sweet Potato and Asparagus',
  'dinner',
  575, 44, 46, 24,
  30,
  'MALZEMELER:
- 180 g somon fileto
- 220 g tatlı patates
- 100 g kuşkonmaz
- 1 yemek kaşığı zeytinyağı
- 1 limon
- tuz, karabiber, dereotu

HAZIRLANIŞI:
1. Tatlı patatesi küp doğrayıp 200 derecede 20 dakika fırınlayın.
2. Somonu ve kuşkonmazı tepsiye ekleyin, yağı gezdirip tatlandırın.
3. Somon lif lif ayrılana kadar 12 dakika daha fırınlayın.
4. Servis etmeden önce limonu üzerine sıkın.',
  'INGREDIENTS:
- 180 g salmon fillet
- 220 g sweet potato
- 100 g asparagus
- 1 tbsp olive oil
- 1 lemon
- salt, pepper, dill

METHOD:
1. Cube the sweet potato and roast at 200 degrees for 20 minutes.
2. Add the salmon and asparagus to the tray, drizzle with oil and season.
3. Roast for a further 12 minutes until the salmon flakes.
4. Squeeze the lemon over everything before serving.',
  ARRAY['high_protein', 'bulking']::text[],
  'american',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY['en']::text[],
