-- Garlic Butter Chicken and Greens
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'garlic-butter-chicken-thighs'),
  'Sarımsaklı Tereyağlı Tavuk ve Yeşillik',
  'Garlic Butter Chicken and Greens',
  'dinner',
  490, 48, 16, 26,
  30,
  'MALZEMELER:
- 200 g tavuk but
- 150 g taze fasulye
- 100 g mantar
- 15 g tereyağı
- 3 diş sarımsak
- kekik, tuz, karabiber

HAZIRLANIŞI:
1. Tavuğu tatlandırıp derili tarafı altta 7 dakika mühürleyin.
2. Çevirin, tereyağı, sarımsak ve kekiği ekleyip 5 dakika yağıyla besleyin.
3. Tavuğu alıp dinlendirin.
4. Mantar ve taze fasulyeyi aynı tavada 6 dakika pişirin.',
  'INGREDIENTS:
- 200 g chicken thigh
- 150 g green beans
- 100 g mushrooms
- 15 g butter
- 3 cloves garlic
- thyme, salt, pepper

METHOD:
1. Season the chicken and sear it skin-side down for 7 minutes.
2. Turn it, add the butter, garlic and thyme, and baste for 5 minutes.
3. Lift the chicken out and rest it.
