-- Lean Beef Stir Fry
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'lean-beef-stir-fry'),
  'Yağsız Dana Etli Sote',
  'Lean Beef Stir Fry',
  'dinner',
  555, 46, 52, 18,
  20,
  'MALZEMELER:
- 180 g dana bonfile
- 80 g yasemin pirinci (kuru ölçü)
- 80 g renkli biber
- 80 g brokoli
- 2 yemek kaşığı soya sosu
- 1 yemek kaşığı susam yağı
- 1 tatlı kaşığı zencefil rende

HAZIRLANIŞI:
1. Pirinci pişirip sıcak tutun.
2. Eti liflerine dik ince dilimleyin.
3. Eti çok kızgın wokta 90 saniye mühürleyip çıkarın.
4. Sebzeleri zencefille soteleyin, eti geri koyup soya sosunu ekleyin.
5. Pilavın üzerinde servis edin.',
  'INGREDIENTS:
- 180 g beef sirloin
- 80 g jasmine rice (dry weight)
- 80 g bell pepper
- 80 g broccoli
- 2 tbsp soy sauce
- 1 tbsp sesame oil
- 1 dessertspoon grated ginger

METHOD:
1. Cook the rice and keep it warm.
2. Slice the beef thinly against the grain.
3. Sear the beef in a very hot wok for 90 seconds and lift it out.
4. Stir-fry the vegetables with the ginger, return the beef, and add the soy sauce.
5. Serve over the rice.',
  ARRAY['high_protein', 'bulking']::text[],
  'american',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY['en']::text[],
