-- Turkey Meatballs in Marinara
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'turkey-meatballs-marinara'),
  'Domates Soslu Hindi Köftesi',
  'Turkey Meatballs in Marinara',
  'dinner',
  440, 46, 24, 18,
  35,
  'MALZEMELER:
- 200 g hindi kıyma
- 1 yumurta
- 20 g galeta unu
- 300 g şekersiz domates sosu
- 2 diş sarımsak
- 1 yemek kaşığı zeytinyağı
- fesleğen, tuz, karabiber

HAZIRLANIŞI:
1. Hindi kıymasını, yumurtayı, galeta ununu ve baharatları karıştırıp köfte yapın.
2. Köfteleri zeytinyağında her tarafı kızarana kadar mühürleyin.
3. Sarımsağı ve domates sosunu ekleyip 18 dakika pişirin.
4. Elle koparılmış fesleğenle bitirin.',
  'INGREDIENTS:
- 200 g ground turkey
- 1 egg
- 20 g breadcrumbs
- 300 g passata
- 2 cloves garlic
- 1 tbsp olive oil
- basil, salt, pepper

METHOD:
1. Mix the turkey, egg, breadcrumbs and seasoning and roll into balls.
2. Brown the meatballs in the olive oil on all sides.
3. Add the garlic and passata and simmer for 18 minutes.
4. Finish with torn basil.',
