-- Baked Cod with Roasted Vegetables
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'cod-with-roasted-vegetables'),
  'Fırında Morina ve Sebzeler',
  'Baked Cod with Roasted Vegetables',
  'dinner',
  390, 40, 30, 12,
  30,
  'MALZEMELER:
- 200 g morina fileto
- 150 g kabak
- 150 g renkli biber
- 100 g cherry domates
- 1 yemek kaşığı zeytinyağı
- 1 limon
- kekik, tuz, karabiber

HAZIRLANIŞI:
1. Sebzeleri iri doğrayıp 200 derecede 18 dakika fırınlayın.
2. Morinayı üzerine yerleştirin, tatlandırın ve limon dilimlerini ekleyin.
3. Balık matlaşana kadar 12 dakika daha fırınlayın.',
  'INGREDIENTS:
- 200 g cod fillet
- 150 g courgette
- 150 g bell pepper
- 100 g cherry tomatoes
- 1 tbsp olive oil
- 1 lemon
- oregano, salt, pepper

METHOD:
1. Cut the vegetables into chunks and roast at 200 degrees for 18 minutes.
2. Lay the cod on top, season it and add the lemon slices.
3. Return to the oven for 12 minutes until the fish is opaque.',
