-- Chicken Fajita Skillet
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'chicken-fajita-skillet'),
  'Tavuklu Fajita Tavası',
  'Chicken Fajita Skillet',
  'dinner',
  465, 46, 34, 16,
  25,
  'MALZEMELER:
- 200 g tavuk göğsü
- 150 g renkli biber
- 1 kuru soğan
- 2 mısır tortilla
- 1 yemek kaşığı zeytinyağı
- 2 çay kaşığı füme toz biber
- kimyon, tuz, karabiber

HAZIRLANIŞI:
1. Tavuğu, biberleri ve soğanı şerit şerit doğrayın.
2. Tavuğu toz biber ve kimyonla harmanlayın.
3. Tavuğu kızgın tavada 6 dakika mühürleyip çıkarın.
4. Biber ve soğanı 5 dakika kavurun, tavuğu geri koyun ve ısıtılmış tortillayla servis edin.',
  'INGREDIENTS:
- 200 g chicken breast
- 150 g bell pepper
- 1 onion
- 2 corn tortillas
- 1 tbsp olive oil
- 2 tsp smoked paprika
- cumin, salt, pepper

METHOD:
1. Slice the chicken, peppers and onion into strips.
2. Toss the chicken with the paprika and cumin.
3. Sear the chicken in a hot skillet for 6 minutes, then lift it out.
4. Char the peppers and onion for 5 minutes, return the chicken, and serve with warm tortillas.',
