-- Protein Shepherd's Pie
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'shepherds-pie-protein'),
  'Proteinli Çoban Güveci',
  'Protein Shepherd''s Pie',
  'dinner',
  590, 48, 54, 20,
  45,
  'MALZEMELER:
- 200 g yağsız dana kıyma
- 300 g patates
- 80 g bezelye
- 1 havuç
- 1 kuru soğan
- 60 ml süt
- kekik, tuz, karabiber

HAZIRLANIŞI:
1. Patatesleri 18 dakika haşlayıp sütle püre yapın.
2. Doğranmış soğan ve havucu yumuşatın, sonra kıymayı ekleyip kavurun.
3. Bezelye ve kekiği karıştırıp karışımı fırın kabına yayın.
4. Üzerini püreyle kapatıp 200 derecede 20 dakika pişirin.',
  'INGREDIENTS:
- 200 g lean ground beef
- 300 g potato
- 80 g peas
- 1 carrot
- 1 onion
- 60 ml milk
- thyme, salt, pepper

METHOD:
1. Boil the potatoes for 18 minutes, then mash them with the milk.
2. Soften the diced onion and carrot, then brown the beef with them.
3. Stir in the peas and thyme and spread the mixture in a baking dish.
4. Top with the mash and bake at 200 degrees for 20 minutes.',
