-- Blackened Chicken with Quinoa
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'blackened-chicken-quinoa'),
  'Baharatlı Tavuk ve Kinoa',
  'Blackened Chicken with Quinoa',
  'dinner',
  500, 50, 44, 14,
  25,
  'MALZEMELER:
- 200 g tavuk göğsü
- 70 g kinoa (kuru ölçü)
- 100 g ıspanak
- 1 yemek kaşığı zeytinyağı
- 2 çay kaşığı cajun baharatı
- 1 limon

HAZIRLANIŞI:
1. Kinoayı 15 dakika haşlayıp kabartın.
2. Tavuğu bolca cajun baharatına bulayın.
3. Çok kızgın tavada her yüzü 5 dakika, kabuk koyulaşana kadar pişirin.
4. Ispanağı aynı tavada soldurup kinoa ve limonla servis edin.',
  'INGREDIENTS:
- 200 g chicken breast
- 70 g quinoa (dry weight)
- 100 g spinach
- 1 tbsp olive oil
- 2 tsp cajun spice
- 1 lemon

METHOD:
1. Simmer the quinoa for 15 minutes and fluff it.
2. Coat the chicken heavily in the cajun spice.
3. Sear it in a very hot pan for 5 minutes a side until the crust is dark.
4. Wilt the spinach in the same pan and serve with the quinoa and lemon.',
  ARRAY['high_protein', 'toning']::text[],
  'american',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/blackened-chicken-quinoa.webp'
)
