-- Teriyaki Tofu Rice Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'tofu-teriyaki-rice'),
  'Teriyaki Tofulu Pirinç Kasesi',
  'Teriyaki Tofu Rice Bowl',
  'dinner',
  530, 30, 66, 16,
  25,
  'MALZEMELER:
- 200 g katı tofu
- 80 g yasemin pirinci (kuru ölçü)
- 100 g brokoli
- 2 yemek kaşığı soya sosu
- 1 yemek kaşığı akçaağaç şurubu
- 1 yemek kaşığı susam yağı
- 1 çay kaşığı susam

HAZIRLANIŞI:
1. Tofuyu suyunu vermesi için 10 dakika presleyin, sonra küp doğrayın.
2. Pirinci pişirin, brokoliyi buharda haşlayın.
3. Tofuyu susam yağında her yüzü altın rengi olana kadar kızartın.
4. Soya sosu ve akçaağaç şurubunu ekleyip tofunun üzerinde koyulaştırın.
5. Pilavın üzerinde susamla servis edin.',
  'INGREDIENTS:
- 200 g firm tofu
- 80 g jasmine rice (dry weight)
- 100 g broccoli
- 2 tbsp soy sauce
- 1 tbsp maple syrup
- 1 tbsp sesame oil
- 1 tsp sesame seeds

METHOD:
1. Press the tofu for 10 minutes to drive the water out, then cube it.
2. Cook the rice and steam the broccoli.
3. Fry the tofu in the sesame oil until every side is golden.
4. Add the soy sauce and maple syrup and let them reduce onto the tofu.
5. Serve over the rice with the sesame seeds.',
  ARRAY['high_protein', 'budget_friendly']::text[],
  'american',
  ARRAY['vegan', 'vegetarian', 'pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/tofu-teriyaki-rice.webp'
)
