-- Turkey Stuffed Peppers
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'stuffed-peppers-turkey'),
  'Hindi Kıymalı Biber Dolması',
  'Turkey Stuffed Peppers',
  'dinner',
  420, 40, 34, 14,
  45,
  'MALZEMELER:
- 3 dolmalık biber
- 180 g hindi kıyma
- 60 g esmer pirinç (kuru ölçü)
- 150 g şekersiz domates sosu
- 1 kuru soğan
- kimyon, tuz, karabiber

HAZIRLANIŞI:
1. Pirinci 20 dakika pişirin.
2. Hindi kıymasını doğranmış soğan ve kimyonla kavurun.
3. Pirinci ve domates sosunun yarısını etin içine karıştırın.
4. İçi boşaltılmış biberleri doldurun, kalan sosu etrafına dökün ve 190 derecede 30 dakika pişirin.',
  'INGREDIENTS:
- 3 bell peppers
- 180 g ground turkey
- 60 g brown rice (dry weight)
- 150 g passata
- 1 onion
- cumin, salt, pepper

METHOD:
1. Cook the rice for 20 minutes.
2. Brown the turkey with the diced onion and cumin.
3. Fold the rice and half the passata through the meat.
4. Fill the hollowed peppers, pour the rest of the passata around them, and bake at 190 degrees for 30 minutes.',
  ARRAY['high_protein', 'low_calorie']::text[],
  'american',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
