-- High-Protein Chili con Carne
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'chili-con-carne-protein'),
  'Yüksek Proteinli Chili con Carne',
  'High-Protein Chili con Carne',
  'dinner',
  535, 46, 52, 16,
  40,
  'MALZEMELER:
- 200 g yağsız dana kıyma
- 150 g kırmızı barbunya
- 300 g doğranmış domates
- 1 kuru soğan
- 2 diş sarımsak
- 2 çay kaşığı toz acı biber
- kimyon, tuz, karabiber

HAZIRLANIŞI:
1. Soğan ve sarımsağı yumuşatın, sonra kıymayı ekleyip kavurun.
2. Toz acı biber ve kimyonu ekleyip kokusu çıkması için 1 dakika pişirin.
3. Domates ve barbunyayı ekleyip 25 dakika kısık ateşte pişirin.
4. Tatlandırıp servis edin — ertesi gün daha lezzetlidir.',
  'INGREDIENTS:
- 200 g lean ground beef
- 150 g kidney beans
- 300 g chopped tomatoes
- 1 onion
- 2 cloves garlic
- 2 tsp chili powder
- cumin, salt, pepper

METHOD:
1. Soften the onion and garlic, then brown the beef with them.
2. Add the chili powder and cumin and cook for 1 minute to bloom them.
3. Add the tomatoes and beans and simmer for 25 minutes.
4. Season and serve — it is better the next day.',
  ARRAY['high_protein', 'bulking']::text[],
  'american',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
