-- Protein Brownie Bites
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'protein-brownie-bites'),
  'Protein Brownie Topları',
  'Protein Brownie Bites',
  'dessert',
  335, 22, 30, 14,
  25,
  'MALZEMELER:
- 60 g yulaf unu
- 30 g çikolatalı whey protein tozu
- 20 g kakao tozu
- 2 yumurta
- 60 g süzme yoğurt
- 2 yemek kaşığı akçaağaç şurubu

HAZIRLANIŞI:
1. Yumurta, yoğurt ve akçaağaç şurubunu birlikte çırpın.
2. Yulaf ununu, protein tozunu ve kakaoyu fazla karıştırmadan ekleyin.
3. Yağlı kâğıt serili kaba döküp 175 derecede 18 dakika pişirin.
4. Kesmeden önce tamamen soğutun — proteinli hamurlar sıcakken dağılır.',
  'INGREDIENTS:
- 60 g oat flour
- 30 g chocolate whey protein powder
- 20 g cocoa powder
- 2 eggs
- 60 g Greek yogurt
- 2 tbsp maple syrup

METHOD:
1. Whisk the eggs, yogurt and maple syrup together.
2. Fold in the oat flour, protein powder and cocoa without overmixing.
3. Spoon into a lined tin and bake at 175 degrees for 18 minutes.
4. Let them cool fully before cutting — protein bakes are fragile hot.',
  ARRAY['high_protein', 'toning']::text[],
  'american',
  ARRAY['vegetarian', 'pork_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/protein-brownie-bites.webp'
)
