-- Frozen Protein Yogurt Bark
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'frozen-yogurt-bark'),
  'Donmuş Protein Yoğurt Kırığı',
  'Frozen Protein Yogurt Bark',
  'dessert',
  250, 24, 20, 8,
  10,
  'MALZEMELER:
- 300 g süzme yoğurt
- 25 g vanilyalı whey protein tozu
- 80 g karışık orman meyvesi
- 15 g bitter çikolata
- 1 yemek kaşığı bal

HAZIRLANIŞI:
1. Protein tozunu ve balı yoğurda karıştırın.
2. Yağlı kâğıt serili tepsiye 1 cm kalınlığında yayın.
3. Yüzeye orman meyvelerini ve doğranmış çikolatayı serpin.
4. 4 saat dondurup parçalara kırın.',
  'INGREDIENTS:
- 300 g Greek yogurt
- 25 g vanilla whey protein powder
- 80 g mixed berries
- 15 g dark chocolate
- 1 tbsp honey

METHOD:
1. Stir the protein powder and honey through the yogurt.
2. Spread it 1 cm thick on a lined tray.
3. Scatter the berries and chopped chocolate over the surface.
4. Freeze for 4 hours, then snap into shards.',
  ARRAY['high_protein', 'low_calorie']::text[],
  'american',
  ARRAY['vegetarian', 'pork_free', 'gluten_free']::text[],
