-- No-Bake Protein Cheesecake Jar
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'protein-cheesecake-jar'),
  'Pişirmesiz Protein Cheesecake',
  'No-Bake Protein Cheesecake Jar',
  'dessert',
  350, 30, 26, 14,
  15,
  'MALZEMELER:
- 150 g süzme peynir
- 80 g süzme yoğurt
- 25 g vanilyalı whey protein tozu
- 2 çavdar kraker
- 1 tatlı kaşığı tereyağı
- 60 g çilek

HAZIRLANIŞI:
1. Süzme peynir, yoğurt ve protein tozunu tamamen pürüzsüz olana kadar blenderdan geçirin — peynirin dokusu tamamen kaybolmalı.
2. Krakerleri ezip erimiş tereyağıyla karıştırarak taban yapın.
3. Kavanozda tabanı ve kremayı katmanlayın.
4. 2 saat soğutup üzerine dilimlenmiş çilek koyun.',
  'INGREDIENTS:
- 150 g cottage cheese
- 80 g Greek yogurt
- 25 g vanilla whey protein powder
- 2 rye crackers
- 1 dessertspoon butter
- 60 g strawberries

METHOD:
1. Blend the cottage cheese, yogurt and protein powder completely smooth — cottage cheese has to lose its texture entirely.
2. Crush the crackers and mix them with the melted butter for the base.
3. Layer the base and the filling in a jar.
4. Chill for 2 hours and top with sliced strawberries.',
  ARRAY['high_protein', 'toning']::text[],
  'american',
  ARRAY['vegetarian', 'pork_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/protein-cheesecake-jar.webp'
)
