-- Chocolate Protein Mug Cake
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'protein-mug-cake'),
  'Çikolatalı Protein Kupa Kek',
  'Chocolate Protein Mug Cake',
  'dessert',
  330, 28, 28, 12,
  5,
  'MALZEMELER:
- 30 g çikolatalı whey protein tozu
- 20 g yulaf unu
- 1 yumurta
- 60 ml süt
- 1 çay kaşığı kabartma tozu
- 1 tatlı kaşığı kakao tozu

HAZIRLANIŞI:
1. Her şeyi doğrudan büyük bir kupada topak kalmayana kadar çırpın.
2. Mikrodalgada yüksek ayarda 60 saniye pişirin.
3. Islak görünse bile 60 saniyede durun — proteinli kek fazla pişince anında lastikleşir.',
  'INGREDIENTS:
- 30 g chocolate whey protein powder
- 20 g oat flour
- 1 egg
- 60 ml milk
- 1 tsp baking powder
- 1 dessertspoon cocoa powder

METHOD:
1. Whisk everything directly in a large mug until no lumps remain.
2. Microwave on high for 60 seconds.
3. Stop at 60 seconds even if it looks wet — protein cake goes rubbery the moment it is overcooked.',
