-- Cinnamon Protein Rice Pudding
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'protein-rice-pudding'),
  'Tarçınlı Protein Sütlaç',
  'Cinnamon Protein Rice Pudding',
  'dessert',
  390, 24, 56, 8,
  30,
  'MALZEMELER:
- 70 g pirinç
- 400 ml süt
- 25 g vanilyalı whey protein tozu
- 1 yemek kaşığı bal
- 1 çay kaşığı tarçın

HAZIRLANIŞI:
1. Pirinci sütte 25 dakika, sık sık karıştırarak pişirin.
2. Ateşten alıp 5 dakika soğumaya bırakın.
3. Protein tozunu ateşten uzakta karıştırın — kaynatmak tozu topaklandırır.
4. Bal ve tarçınla bitirin.',
  'INGREDIENTS:
- 70 g rice
- 400 ml milk
- 25 g vanilla whey protein powder
- 1 tbsp honey
- 1 tsp cinnamon

METHOD:
1. Simmer the rice in the milk for 25 minutes, stirring often.
2. Take it off the heat and let it cool for 5 minutes.
3. Stir the protein powder in off the heat — boiling it makes it grainy.
4. Finish with honey and cinnamon.',
  ARRAY['high_protein', 'budget_friendly']::text[],
  'american',
  ARRAY['vegetarian', 'pork_free', 'gluten_free']::text[],
  ARRAY['en']::text[],
  'photos/meals/protein-rice-pudding.webp'
)
